// REVIEW COPY of src/sim/bot.ts (docs/reviews/POSITIONING-AND-ECONOMY.md) with internals exported and knobs. Not used by the game.
// Generated by tools/review/mkbotx.ts: do not edit, regenerate it.
// Planning bots for the tournament and the vs-AI mode. Bots see only viewFor() (no hidden information: their own
// state plus the enemy's public view, i.e. the army as it fought LAST round) and act only through applyIntent, so
// they obey exactly the same rules as players.
//
// The vs-AI difficulties (src/net/protocol.ts AI_STRATEGY) are three genuinely different players:
//  - 'easy':   spends only ~65% of its gold, rarely levels up, drafts / loots / equips at random, ignores the enemy
//              army when buying, and lines everything up in one naive row.
//  - 'normal': the counter-picker. Reads the counter wheel exactly as Hard does (one unitScore for every level) but
//              misjudges more: buys and unlocks counters to the enemy's last army, keeps a frontline, keeps part of
//              its gold in reserve (per Lord, NORMAL_RESERVE), levels a squad instead of a weak buy, equips each item on the most
//              valuable squad it works on, and sets each new squad down in its role lane opposite what it beats (slow
//              melee a little further forward, fast melee further back). It never re-forms squads already placed,
//              except its archers, which move under the enemy's fliers.
//  - 'hard':   ('best' is an alias) spends everything, choosing each time between the best counter-buy and levelling a
//              squad that counters the enemy, re-forms the whole army every round against the enemy's last formation
//              (pikes in front of enemy cavalry, raiders on the flank with the enemy backline, archers under enemy
//              fliers...) with its melee staggered in depth by speed so it reaches the river together, and puts each
//              item on the squad its affixes suit.
// Relocation (DESIGN §2): a squad is locked where it was deployed, so every level places for the long term (a new squad
// goes opposite what it beats in the enemy's army, which is locked too, and melee is set back by speed against a fixed
// reference so later squads still arrive together). Hard and Normal call Muster instead of the round's unlock when the
// squads they could relocate stand far from where they are needed (musterWorth); Easy never does.
// Every level saves up for a dear unit it wants (saveFor): income is 225-500 a round, so a Dragon is never bought
// by a bot that spends everything each round.
import { mirrorPos } from '../../src/sim/constants.ts';
import { CLASSIC_RESERVE, NORMAL_RESERVE } from '../../src/sim/data/balance.ts';
import { LORDS, LORD_IDS } from '../../src/sim/data/lords.ts';
import { AFFIXES, LEGENDARY_POWER, SLOT_UNLOCK_LEVEL } from '../../src/sim/data/items.ts';
import { SKILLS, UNIT_CLASS, canEquip } from '../../src/sim/data/skills.ts';
import { beatenBy, classBeats } from '../../src/sim/data/wheel.ts';
import { UNITS, formationOf, hasFormation } from '../../src/sim/data/units.ts';
import { itemPower, legendaryFits, wheelClassOf } from '../../src/sim/loot.ts';
import { beatsClass } from '../../src/sim/data/wheel.ts';
import { ARMY_CAP, MAX_SQUAD_LEVEL, MUSTER_MOVES, applyIntent, canMuster, income, deployWeight, deployZone, freeSpotNear, levelUpCost, relocationsLeft, slotOpen, squadFootprint, squadHome, squadLocked, viewFor } from '../../src/sim/match.ts';
import { hash } from '../../src/sim/rng.ts';
import type { BotStrategy, Formation, Item, KingdomUnit, LordId, MatchState, PlayerState, Seat, Slot, Squad, SquadType, Tag, UnitType, Vec2, WheelClass } from '../../src/sim/types.ts';

/**
 * Every faction's units are understood through the Kingdom unit they play like (UnitDef.like): the preference and
 * counter tables below are written once, for the Kingdom roster, and K() maps any unit onto them.
 */
const K = (u: UnitType): KingdomUnit => UNITS[u].like;
const KT = (t: SquadType): KingdomUnit | 'lord' => (t === 'lord' ? 'lord' : UNITS[t].like);

export const BOT_STRATEGIES: readonly BotStrategy[] = ['rush', 'ranged', 'armor', 'air', 'counter', 'random', 'best', 'easy', 'normal', 'hard'];

type Flavour = 'rush' | 'ranged' | 'armor' | 'air';
/** A flavoured strategy's weight for a unit its taste does not list. */
const FLAVOUR_REST = 0.7;
/** Preference weights per strategy (unlisted units get FLAVOUR_REST; 'random' is flat). */
const PREF: Record<Flavour, Partial<Record<UnitType, number>>> = {
  rush: { militia: 2.5, berserkers: 2.5, cavaliers: 2.5, pikemen: 1.5, knights: 1.5, wyvern: 1.5, golem: 1, archers: 1.5 },
  ranged: { archers: 4, mages: 4, ballista: 3, trebuchet: 3, clerics: 2, pikemen: 2, knights: 2, militia: 2 },
  armor: { knights: 4, golem: 4, pikemen: 3, clerics: 3, mages: 2, militia: 2, berserkers: 1 },
  air: { pegasus: 2.2, wyvern: 2.2, dragon: 2.6, archers: 1.5, clerics: 1, militia: 1.5, knights: 1 },
};

/**
 * The counter wheel, as the bots read it (DESIGN §3, data/wheel.ts). A body is a unit type or a Lord (a Lord fights
 * as the class of its body or mount). WHEEL_CV is what a counter is worth on the bots' 0..4 scale.
 */
interface Body { class: WheelClass; tags: readonly Tag[]; range: number; weapon: string; damageType: string; armor: number; magicResist: number; traits: readonly string[] }
const NO_TRAITS: readonly string[] = [];
function bodyOf(t: UnitType | 'lord', lord: LordId | null): Body | null {
  if (t !== 'lord') return UNITS[t];
  if (!lord) return null;
  const L = LORDS[lord];
  return { class: L.class, tags: L.tags, range: L.range, weapon: L.weapon, damageType: L.damageType, armor: L.armor, magicResist: L.magicResist, traits: NO_TRAITS };
}
const canHitAir = (A: Body): boolean => (A.range > 400 && A.weapon !== 'stone') || A.tags.includes('flier') || A.traits.includes('howdah') || A.traits.includes('healer');
const WHEEL_CV = 3;

/**
 * How well body A beats body B (0..4): WHEEL_CV when A's class beats B's on the wheel, else 0, shaded by the stats the
 * wheel leaves in place (they must never contradict it, but they still matter): a melee unit cannot touch a flier at all,
 * warded targets shrug off magic, ethereal ones take more of it, heavy armour blunts steel, and a healer barely fights.
 */
function wheelCv(A: Body, B: Body): number {
  if (B.tags.includes('flier') && !canHitAir(A)) return 0;
  let v = classBeats(A.class, B.class) ? WHEEL_CV : 0;
  const magic = A.damageType === 'magic' || A.traits.includes('ignoresArmor');
  if (magic && B.magicResist < 0) v += 1;
  if (A.damageType === 'magic' && B.magicResist >= 40) v -= 1;
  if (!magic && B.armor >= 45 && !A.traits.includes('crushing')) v -= 0.5;
  // What a unit is built for inside its class: a braced spear wall against a charge, a raider against a backline it
  // can ride or fly to (this is what tells Pikemen from Knights and Pegasus Knights from Wyverns).
  if (A.traits.includes('brace') && B.traits.includes('charge')) v += 0.7;
  if (A.traits.includes('raider') && B.traits.includes('backline')) v += 0.7;
  if (A.traits.includes('healer')) v *= 0.3;
  return v < 0 ? 0 : v;
}

/** Units that hold a line on the ground. Fliers are not a frontline: ground troops walk under them to the archers. */
const FRONT: ReadonlySet<UnitType> = new Set(['militia', 'pikemen', 'berserkers', 'knights', 'cavaliers', 'golem']);

/** sqrt by Newton iteration (src/sim avoids Math.sqrt so the grep test stays strict; bots only use it for weights). */
function fsqrt(x: number): number {
  if (x <= 0) return 0;
  let r = x > 1 ? x : 1;
  for (let i = 0; i < 30; i++) r = 0.5 * (r + x / r);
  return r;
}

function rnd01(...parts: (string | number)[]): number {
  return (hash(...parts) % 10000) / 10000;
}

/** What an enemy Lord is worth as a threat to counter-buy against (a Lord has a class on the wheel like any squad). */
const LORD_THREAT_VALUE = 300;

/**
 * Playing to the Lord's passive: how much more a bot wants a unit its Lord's passive favours. One weight for every
 * level (the classic planner used to carry its own column of weights, tuned before the counter wheel; they no longer
 * matched the game and made Normal play some Lords against their own passive).
 */
const LORD_PLAY: Partial<Record<LordId, { fits: (u: UnitType) => boolean; w: number }>> = {
  archmage: { fits: (u) => UNITS[u].damageType === 'magic' && !UNITS[u].traits.includes('healer'), w: 1.5 }, // magic damage +70%
  deathknight: { fits: (u) => UNIT_CLASS[u] === 'infantry', w: 1.2 }, // infantry hits harder
  ossuary: { fits: (u) => UNITS[u].armor >= 30, w: 1.2 }, // armour stacks on armour
  drakerider: { fits: (u) => UNITS[u].speed >= 20, w: 1.1 }, // the quick ones get there first
  vizier: { fits: (u) => UNITS[u].damageType === 'magic', w: 1.35 }, // magic attacks faster (heals too)
  rajah: { fits: (u) => UNIT_CLASS[u] === 'giant', w: 1.5 }, // tougher giants
  rocrider: { fits: (u) => UNIT_CLASS[u] === 'ranged', w: 1.3 }, // archers hit harder
};
function lordAffinity(lord: LordId | null, u: UnitType): number {
  const k = lord ? LORD_PLAY[lord] : undefined;
  return k && k.fits(u) ? k.w : 1;
}
/** Lords whose hero is a tank: the classic planner values their gear like the Warden's (WARDEN_GEAR). */
const TANK_LORDS: ReadonlySet<LordId> = new Set(['warden', 'ossuary', 'rajah']);

type Level = 'easy' | 'normal' | 'hard' | 'classic';
/** Which planner a strategy uses: the three vs-AI levels, or the classic tournament planner (flavours, random, counter). */
function levelOf(strat: BotStrategy): Level {
  if (strat === 'easy') return 'easy';
  if (strat === 'normal') return 'normal';
  if (strat === 'hard' || strat === 'best' || strat === 'hardx') return 'hard';
  return 'classic';
}

const units = (sq: readonly Squad[]): Squad[] => sq.filter((q) => q.type !== 'lord');
const valueOf = (q: Squad): number => (q.type === 'lord' ? 450 : UNITS[q.type].cost * (1 + 0.5 * (q.level - 1)));

/** What the enemy fielded last round, in this bot's frame (`body`: its stats and wheel class; a Lord's are its own). */
interface Threat { type: UnitType | 'lord'; value: number; x: number; y: number; tags: readonly Tag[]; magic: boolean; ranged: boolean; backline: boolean; body: Body }

/** Hard's lean towards dearer units (see unitScore): weight = [0] + [1] x cost / 200. */
const HARD_COST_LEAN: [number, number] = [0.8, 0.2];
/** What a flier is worth against an enemy squad that cannot reach it at all, on the bots' 0..4 scale. */
const AIR_FREE_CV = 0.5;
/** A first healer's worth (the counter scale's neutral is 1.2) behind an army that fights hand to hand: [base, per melee share]. */
const HEALER_WORTH: [number, number] = [1.3, 1.6];
/** How much the unit scores of each level wobble (a weaker player misjudges more). */
const SCORE_NOISE: Record<Level, number> = { hard: 0.1, normal: 0.3, classic: 0.2, easy: 0 };

/**
 * How much a bot wants unit `u` now. One wheel reading for every level (Hard, Normal and the classic tournament
 * strategies used to carry two; the classic one never discounted threats its own army already answered, so it stacked
 * one counter class and walked into the class that beats it):
 *  - counter value on the wheel against the part of the enemy's last army that its own army does not already answer,
 *    less what that army does to the unit (wheelCv), and a little for a flier the enemy cannot reach;
 *  - the sensible-play rules: enemy fliers need an answer, keep a frontline, one healer behind a melee army, do not
 *    stack one type, play to the Lord's passive.
 * The levels differ in skill, not in rules: Hard also leans to the dearer unit when two are close and misjudges least;
 * the flavoured tournament strategies bend the counter value by their taste (PREF). Only public information.
 */
function unitScore(s: MatchState, seat: Seat, strat: BotStrategy, u: UnitType, mine: Squad[], threats: Threat[], salt: number): number {
  const def = UNITS[u];
  const level = levelOf(strat);
  const army = units(mine);
  const flier = def.tags.includes('flier');
  let w = 1.2;
  if (threats.length) {
    let num = 0, den = 0;
    for (const e of threats) {
      // The enemy Lord counts as a threat of its wheel class, at a squad's value.
      const ev = e.type === 'lord' ? LORD_THREAT_VALUE : e.value;
      let cover = 0;
      for (const m of army) cover += wheelCv(UNITS[m.type as UnitType], e.body) * valueOf(m);
      const weight = ev / (1 + cover / Math.max(1, ev));
      num += weight * (wheelCv(def, e.body) - 0.7 * wheelCv(e.body, def) + (flier && !canHitAir(e.body) ? AIR_FREE_CV : 0));
      den += weight;
    }
    w = Math.max(0.15, 1.2 + (2.2 * num) / Math.max(1, den));
  }
  // The tournament strategies' taste. A flavoured strategy reads the wheel in full and multiplies it by its taste (it
  // used to take the square root of the counter value, so 'air' kept buying fliers into a wall of bows and the units it
  // loves read 30-40% in the field for the strategy's sake, not their own).
  if (strat === 'random') w = (1 + 2 * rnd01(s.seed, s.round, seat, u, salt, 'r')) * fsqrt(w);
  else if (level === 'classic' && strat !== 'counter') w = (PREF[strat as Flavour][K(u)] ?? FLAVOUR_REST) * w;
  // Sensible play for every strategy: enemy fliers must be answered by something that can hit them at all. (The wheel
  // already says Ranged beats Air; this only keeps the army from being helpless against fliers.)
  if (threats.length) {
    let air = 0, all = 0;
    for (const e of threats) { all += e.value; if (e.tags.includes('flier')) air += e.value; }
    const fa = air / Math.max(1, all);
    const antiAir = (def.range > 400 && def.weapon !== 'stone' && !def.traits.includes('healer')) || flier;
    let mineAir = 0;
    for (const m of army) { const d = UNITS[m.type as UnitType]; if ((d.range > 400 && d.weapon !== 'stone') || d.tags.includes('flier')) mineAir += valueOf(m); }
    const airCover = mineAir / Math.max(1, air);
    if (fa > 0.1) w *= antiAir ? 1 + (2.5 * fa) / (1 + airCover) : 1 - 0.4 * fa;
  }
  // A healer is not a counter to anything: its worth is the army it keeps standing (one, behind squads that fight
  // hand to hand, once there is an army to heal).
  if (def.traits.includes('healer')) {
    let melee = 0, all = 0;
    for (const m of army) { const v = valueOf(m); all += v; if (UNITS[m.type as UnitType].range <= 400) melee += v; }
    w = Math.max(w, HEALER_WORTH[0] + (HEALER_WORTH[1] * melee) / Math.max(1, all));
    if (army.some((q) => UNITS[q.type as UnitType].traits.includes('healer'))) w *= 0.25;
    if (army.length < 3) w *= 0.5;
  } else {
    // Keep a frontline: at least ~half the squads must be front units.
    const front = army.filter((q) => FRONT.has(K(q.type as UnitType))).length;
    const short = front < Math.ceil((army.length + 1) / 2);
    if (short) w *= FRONT.has(K(u)) ? 1.8 : 0.6;
  }
  // Diminishing returns on stacking one type.
  w /= 1 + 0.3 * army.filter((q) => q.type === u).length;
  // Signature units of your Lord are cheaper to love; and play to the Lord's passive.
  const lord = s.players[seat].lord;
  if (lord && LORDS[lord].signature.includes(u)) w *= 1.2;
  w *= lordAffinity(lord, u);
  // Spending gold well (Hard only): prefer the stronger buy when two are close. (Deploy points are weighted by cost, so
  // a big unit is no longer much better per deploy than a cheap one: the lean is mild.)
  if (level === 'hard') w *= HARD_COST_LEAN[0] + HARD_COST_LEAN[1] * (def.cost / 200);
  const noise = SCORE_NOISE[level];
  w *= 1 - noise / 2 + noise * rnd01(s.seed, s.round, seat, u, salt, 'hj');
  return w;
}

// ---------------------------------------------------------------- shared helpers

/** Seat-local frame: the bot's own deploy zone is low y and the enemy is at high y (seat 1 works mirrored). */
const own = (seat: Seat, p: Vec2): Vec2 => (seat === 0 ? [p[0], p[1]] : mirrorPos(p));


/** Deterministic slot for a new squad by its role, in seat 0 coordinates: lanes across the field in deploy order, rows by role. */
export function placeFor(u: UnitType | 'lord', squads: readonly Squad[], lord: LordId | null): Vec2 {
  const k = squads.filter((q) => q.type !== 'lord').length;
  const lanes = [3999, 2600, 5400, 1300, 6700, 3300, 4700, 2000, 6000];
  const x = lanes[k % lanes.length];
  // A Lord who shoots or flies starts behind the army (a flier sent ahead alone meets every bow on the field).
  // The Ossuary Warden stands in the front line: Grave Taunt needs the enemy around him.
  if (u === 'lord') return lord && (LORDS[lord].range > 400 || LORDS[lord].tags.includes('flier')) ? [3999, 1500] : lord === 'ossuary' ? [3999, 3300] : [3999, 2600];
  const def = UNITS[u], ku = K(u);
  let y: number;
  if (ku === 'trebuchet') y = 700;
  else if (ku === 'ballista' || ku === 'clerics') y = 1500;
  else if (def.range > 400) y = 2100;
  else if (ku === 'cavaliers' || ku === 'pegasus' || ku === 'wyvern') y = 2900;
  else y = 3500;
  const row = Math.floor(k / lanes.length);
  return [x, Math.max(400, y - row * 600)];
}

/**
 * Normal's weaker version of Hard's speed stagger (speedStagger): a melee squad is set back by its march speed
 * against a fixed reference (a Knight's pace), half-way from its lane's row, so slow squads stand in front and fast
 * ones further back. Normal never re-forms, so this happens once, when the squad is deployed.
 */
const NORMAL_STAGGER_REF = 11;
const NORMAL_STAGGER_PCT = 50;
function normalDepth(u: UnitType, want: Vec2): Vec2 {
  const d = UNITS[u];
  if (d.range > 400) return want;
  const synced = 6000 - Math.round((2500 * d.speed) / NORMAL_STAGGER_REF);
  const y = Math.round((want[1] * (100 - NORMAL_STAGGER_PCT) + Math.max(400, Math.min(3500, synced)) * NORMAL_STAGGER_PCT) / 100);
  return [want[0], Math.max(400, Math.min(3500, y))];
}

/** Deploy `u` as near `want` (seat 0 frame) as the footprint rule allows. */
function deployNear(s: MatchState, seat: Seat, u: UnitType, want: Vec2): boolean {
  const p = s.players[seat];
  const spot = freeSpotNear(p.squads, seat, u, seat === 0 ? want : mirrorPos(want));
  return !!spot && applyIntent(s, seat, { t: 'deploy', unit: u, pos: spot }).ok;
}

/**
 * How much the classic planner values the Warden's hero when choosing who wears an item (percent of his squad value).
 * His hero outlasts nearly every Normal army; with the full value he wore the best of everything and read 60% at
 * Normal (50% at Hard). Spreading his gear over his squads is what a sensible Warden player does (see BALANCE.md).
 */
const WARDEN_GEAR = 25;
/** What a class-locked legendary is worth to the classic planner on a squad of the wrong class (percent of the squad's value). */
const MISFIT_GEAR = 35;
function bestSquadFor(item: Item, squads: Squad[], lord: LordId | null): Squad | null {
  let best: Squad | null = null, bestV = -1;
  for (const q of squads) {
    if (q.type !== 'lord' && q.level < SLOT_UNLOCK_LEVEL[item.slot]) continue;
    // Skill items only go on a squad of the right class.
    if (!canEquip(item, q.type, lord)) continue;
    const cur = q.items[item.slot];
    if (cur && itemPower(cur) >= itemPower(item)) continue;
    // The Warden's hero already outlasts most armies it meets: he shares more of his gear with the squads around him.
    let value = q.type === 'lord' && lord && TANK_LORDS.has(lord) ? WARDEN_GEAR * valueOf(q) / 100 : valueOf(q);
    // A legendary power works only on the classes it is built for ("Best on"): elsewhere the item is just its affixes.
    if (item.legendary && !legendaryFits(item.legendary, q.type, lord)) value *= MISFIT_GEAR / 100;
    const v = value - (cur ? itemPower(cur) * 5 : 0);
    if (v > bestV) { bestV = v; best = q; }
  }
  return best;
}

function pickDrafts(s: MatchState, seat: Seat, choose: (opts: UnitType[]) => UnitType): void {
  for (let guard = 0; guard < 4 && s.players[seat].draftPicks > 0 && s.players[seat].draftOptions.length; guard++) {
    if (!applyIntent(s, seat, { t: 'draft', unit: choose(s.players[seat].draftOptions) }).ok) break;
  }
}

const canDeploy = (p: PlayerState): boolean => p.deploysUsed < p.deployLimit && units(p.squads).length < ARMY_CAP;
/** Do the deploy points left this round cover a `u` squad (deployWeight)? */
const fits = (p: PlayerState, u: UnitType): boolean => p.deploysUsed + deployWeight(u) <= p.deployLimit;

/**
 * Saving up: gold to hold back this round so that a dear unit can be bought next round. Income is 225-500 a round, so
 * a 500-gold Dragon (and often a 400-gold giant) is never affordable to a bot that spends everything every round: it
 * was unlocked and never fielded. When the unit a bot wants most is out of reach now, would be in reach next round with
 * this round's change, and it wants it SAVE_MARGIN times more than the best unit it can afford, it keeps that change.
 */
const SAVE_MARGIN = 1.2;
/** The classic planner pays for a unit dearer than this out of its reserve (see planClassic). */
const DEAR_COST = 400;
function saveFor(s: MatchState, p: PlayerState, avail: number, score: (u: UnitType) => number): number {
  if (units(p.squads).length >= ARMY_CAP - 1) return 0;
  let dear: UnitType | null = null, dw = -1, bw = -1;
  for (const u of p.unlocked) {
    if (deployWeight(u) > p.deployLimit) continue;
    const w = score(u);
    if (UNITS[u].cost <= avail) { if (fits(p, u) && w > bw) bw = w; }
    else if (UNITS[u].cost <= avail + income(s.round + 1) && w > dw) { dw = w; dear = u; }
  }
  if (!dear || dw < SAVE_MARGIN * bw) return 0;
  return Math.max(0, Math.min(avail, UNITS[dear].cost - income(s.round + 1)));
}

/**
 * Where the classic planner sets a new squad down (seat 0 frame): its role lane and row (placeFor), moved across the
 * field to stand opposite the enemy squads its class beats on the wheel, as they stood last round. It never re-forms the
 * squads already down (that is Hard's skill).
 */
function wheelLane(u: UnitType, squads: readonly Squad[], lord: LordId | null, threats: Threat[]): Vec2 {
  const at = placeFor(u, squads, lord);
  const def = UNITS[u];
  if (def.traits.includes('healer') || K(u) === 'trebuchet') return at;
  let n = 0, d = 0;
  for (const e of threats) { const w = wheelCv(def, e.body) * e.value * (e.type === 'lord' ? 0.4 : 1); n += w * e.x; d += w; }
  return d > 0 ? [Math.max(700, Math.min(7300, Math.round(n / d))), at[1]] : at;
}

// ---------------------------------------------------------------- relocation and Muster

/**
 * The bots' relocation judgement. `x` is the experimental set used by the 'hardx' strategy (tools/tournament.ts
 * --strats hard,hardx with OB_KNOBS='{"musterMin":...}' plays a variant against the shipped Hard); everything else
 * plays `base`.
 */
export interface BotKnobs {
  /** Muster is worth calling when the squads it would relocate stand at least this far (cm, summed) from where they are wanted. */
  musterMin: number;
  /** ...and the best unit on offer is at most this much better than the best unit already unlocked (score ratio). */
  musterEdge: number;
  /** ...and (unless nothing is left to unlock) the last round was not won. */
  musterAfterLoss: boolean;
  /** A relocation is not spent on a squad standing closer than this (cm) to its wanted spot. */
  relocateMin: number;
  /** The march speed Hard's stagger is measured against (0: the slowest melee squad in the army, as before the lock). */
  staggerRef: number;
  /** Hard's preference for a level over a new squad (HARD_LEVEL_BIAS). */
  levelBias: number;
  /** Never call Muster. */
  noMuster: boolean;
  /** Leave the Lord on his default stance (advance). */
  noStance: boolean;
  /** Leave every squad in its default formation (deep). */
  noFormation: boolean;
}
const KNOBS: { base: BotKnobs; x: BotKnobs } = {
  base: { musterMin: 6000, musterEdge: 1.15, musterAfterLoss: true, relocateMin: 800, staggerRef: 9, levelBias: 0.5, noMuster: false, noStance: false, noFormation: false },
  x: { musterMin: 6000, musterEdge: 1.15, musterAfterLoss: true, relocateMin: 800, staggerRef: 9, levelBias: 0.5, noMuster: false, noStance: false, noFormation: false },
};
/** Set the experimental knobs of 'hardx' (review tooling only; the game never calls this). */
export function setBotKnobs(k: Partial<BotKnobs>): void { Object.assign(KNOBS.x, KNOBS.base, k); }
const knobsOf = (strat: BotStrategy): BotKnobs => (strat === 'hardx' ? KNOBS.x : KNOBS.base);

/** How far (cm) a squad stands from the spot wanted for it (seat 0 frame): sideways counts in full, depth half. */
function offBy(seat: Seat, q: Squad, want: Vec2): number {
  const [x, y] = own(seat, q.pos);
  return Math.abs(x - want[0]) + Math.abs(y - want[1]) / 2;
}
/**
 * What a Muster would be worth now: the distance (cm, summed) by which the MUSTER_MOVES worst-placed locked squads
 * stand from where `layout` wants them. A squad nearer than `min` is not worth a relocation.
 */
function musterWorth(s: MatchState, seat: Seat, layout: Map<number, Vec2>, min: number): number {
  const p = s.players[seat];
  const off: number[] = [];
  for (const q of p.squads) {
    const w = layout.get(q.id);
    if (!w || !squadLocked(q, s.round)) continue;
    const d = offBy(seat, q, w);
    if (d >= min) off.push(d);
  }
  off.sort((a, b) => b - a);
  let sum = 0;
  for (let i = 0; i < Math.min(MUSTER_MOVES, off.length); i++) sum += off[i];
  return sum;
}
/**
 * Call Muster instead of this round's unlock? Yes when the layout is countered: the last round was not won, the squads
 * a Muster would relocate stand far from where they are wanted against the enemy's army (musterWorth), and no unit on
 * offer is much better than what is already unlocked (`edge`: best offer / best unlocked, by the bot's own unit
 * score). With nothing left to unlock a Muster costs nothing, so any worthwhile relocation calls it.
 */
function considerMuster(s: MatchState, seat: Seat, K: BotKnobs, layout: Map<number, Vec2>, edge: number): boolean {
  const p = s.players[seat];
  if (K.noMuster || !canMuster(p, s.round)) return false;
  const worth = musterWorth(s, seat, layout, K.relocateMin);
  const free = !p.draftOptions.length || p.draftPicks <= 0;
  if (free ? worth < K.relocateMin : worth < K.musterMin || edge > K.musterEdge || (K.musterAfterLoss && !p.lostLast)) return false;
  return applyIntent(s, seat, { t: 'muster' }).ok;
}
/** Best offer against the best unit already unlocked, by `score` (1 when there is nothing to compare). */
function unlockEdge(p: PlayerState, score: (u: UnitType) => number): number {
  let o = 0, h = 0;
  for (const u of p.draftOptions) o = Math.max(o, score(u));
  for (const u of p.unlocked) h = Math.max(h, score(u));
  return h > 0 ? o / h : 1;
}

// ---------------------------------------------------------------- easy

function planEasy(s: MatchState, seat: Seat, salt: number): void {
  const p = s.players[seat];
  const r = (...k: (string | number)[]): number => rnd01(s.seed, s.round, seat, salt, 'easy', ...k);
  pickDrafts(s, seat, (opts) => opts[Math.floor(r('draft', opts.length) * opts.length)]);
  if (p.lootOffer) applyIntent(s, seat, { t: 'pickLoot', index: Math.floor(r('loot') * p.lootOffer.length) });
  // Under-spends: only ~65% of the purse this round.
  let budget = Math.floor(p.gold * (0.6 + 0.1 * r('budget')));
  for (let k = 0; k < 6 && canDeploy(p); k++) {
    const opts = p.unlocked.filter((u) => UNITS[u].cost <= Math.min(budget, p.gold) && fits(p, u));
    if (!opts.length) break;
    const u = opts[Math.floor(r('unit', k) * opts.length)];
    // Naive placement: one row across the middle of the zone, whatever the unit.
    const n = units(p.squads).length;
    if (!deployNear(s, seat, u, [1000 + ((n * 900) % 6000), 2800])) break;
    budget -= UNITS[u].cost;
  }
  // Rarely levels up: one random squad, one round in four.
  if (r('lvl') < 0.25) {
    const cands = units(p.squads).filter((q) => q.level < 5 && levelUpCost(q.type as UnitType, q.level) <= Math.min(budget, p.gold));
    if (cands.length) applyIntent(s, seat, { t: 'levelUp', squad: cands[Math.floor(r('lvlq') * cands.length)].id });
  }
  // Random equips: each stash item onto a random squad with that slot free (sometimes not at all).
  for (const it of [...p.stash]) {
    if (r('eq', it.id) < 0.3) continue;
    const free = p.squads.filter((q) => slotOpen(q, it.slot) && !q.items[it.slot]);
    if (free.length) applyIntent(s, seat, { t: 'equip', item: it.id, squad: free[Math.floor(r('eqq', it.id) * free.length)].id });
  }
  applyIntent(s, seat, { t: 'ready' });
}

// ---------------------------------------------------------------- normal + the classic tournament planner

/**
 * Where the classic planner would want its locked squads now (seat 0 frame): each opposite the enemy squads its class
 * beats, at its own depth. Squads that beat nothing the enemy fields, healers and artillery are left out (they stay).
 */
function wheelSpots(s: MatchState, seat: Seat, threats: Threat[]): Map<number, Vec2> {
  const out = new Map<number, Vec2>();
  for (const q of s.players[seat].squads) {
    if (q.type === 'lord' || !squadLocked(q, s.round)) continue;
    const def = UNITS[q.type];
    if (def.traits.includes('healer') || K(q.type) === 'trebuchet') continue;
    let n = 0, d = 0;
    // Not the enemy Lord: he moves freely every round, so a relocation spent chasing him is wasted.
    for (const e of threats) { if (e.type === 'lord') continue; const w = wheelCv(def, e.body) * e.value; n += w * e.x; d += w; }
    if (d > 0) out.set(q.id, [Math.max(700, Math.min(7300, Math.round(n / d))), own(seat, q.pos)[1]]);
  }
  return out;
}

/** Normal's version of HARD_LEVEL_BIAS (see planClassic). */
const NORMAL_LEVEL_BIAS = 0.4;

function planClassic(s: MatchState, seat: Seat, strat: BotStrategy, salt: number): void {
  const v = viewFor(s, seat);
  const p = s.players[seat];
  const threats = threatsOf(seat, v.enemy.lastArmy, v.enemy.lord);
  const score = (u: UnitType, sl: number): number => unitScore(s, seat, strat, u, p.squads, threats, sl);
  // 0. Muster instead of the unlock when its squads stand far from what they beat (it never re-forms otherwise).
  const KN = knobsOf(strat);
  considerMuster(s, seat, KN, wheelSpots(s, seat, threats), unlockEdge(p, (u) => score(u, salt + 7)));
  // 1. Unlock: the unit that best answers what the enemy fielded (the same wheel reading as its buying).
  pickDrafts(s, seat, (opts) => {
    let best = opts[0], bw = -1;
    for (const u of opts) { const w = score(u, salt + 7); if (w > bw) { bw = w; best = u; } }
    return best;
  });
  // 2. Loot: every item of an offer has the same budget, so take the one that suits some squad of the army best
  //    against the enemy's last army (Normal does not weigh what that squad already wears, as Hard does).
  if (p.lootOffer) {
    let bi = 0, bf = -1;
    p.lootOffer.forEach((it, i) => {
      let f = 0;
      for (const q of p.squads) f = Math.max(f, itemFit(it, q, threats, p.lord));
      if (f > bf) { bf = f; bi = i; }
    });
    applyIntent(s, seat, { t: 'pickLoot', index: bi });
  }
  // The reserve: the share of its gold this planner keeps back, per Lord (data/balance.ts; it is the lever
  // that evens the Lords out at these levels).
  const reserve = p.lord ? Math.floor((p.gold * (strat === 'normal' ? NORMAL_RESERVE : CLASSIC_RESERVE)[p.lord]) / 1000) : 0;
  // A unit that costs more than any round's income before the cap (the 500-gold Dragon) can only ever be bought out of
  // gold kept back: the reserve is there for it (`dear`). (Without this the reserve share of a growing purse kept the
  // Dragon out of reach for ever: Normal unlocked it 217 times and fielded it 7 times. Letting the 400-gold giants
  // through too, or saving up more eagerly, moved Normal's Lords by up to 12 points.)
  const dear = (u: UnitType): boolean => UNITS[u].cost > DEAR_COST;
  const save = saveFor(s, p, p.gold - reserve, (u) => score(u, salt));
  const hold = reserve + save;
  // 3. Spend: deploy up to the limit, then level up. Normal also weighs a level-up against each deployment, like
  //    Hard but by its own unit scores: a squad that counters the enemy well is worth levelling over a weak buy.
  const levelBias = strat === 'normal' ? NORMAL_LEVEL_BIAS : 0;
  for (let guard = 0; guard < 16 && canDeploy(p); guard++) {
    let best: UnitType | null = null, bw = -1;
    for (const u of p.unlocked) {
      // The reserve holds for deployments as for level-ups (it used to spare a Lord with more deployments, the Marshal).
      if (UNITS[u].cost > p.gold - (dear(u) ? save : hold) || !fits(p, u)) continue;
      const w = score(u, salt);
      if (w > bw) { bw = w; best = u; }
    }
    if (!best) break;
    if (levelBias > 0) {
      let lq: Squad | null = null, lw = -1;
      for (const q of units(p.squads)) {
        if (q.level >= MAX_SQUAD_LEVEL || levelUpCost(q.type as UnitType, q.level) > p.gold - hold) continue;
        const w = unitScore(s, seat, strat, q.type as UnitType, p.squads.filter((o) => o !== q), threats, salt + 3) / (1 + 0.25 * (q.level - 1));
        if (w > lw) { lw = w; lq = q; }
      }
      if (lq && lw * levelBias > bw) { if (!applyIntent(s, seat, { t: 'levelUp', squad: lq.id }).ok) break; continue; }
    }
    // Placement: the squad's role lane, opposite what it beats on the wheel (wheelLane); Normal also sets its melee
    // back by speed (normalDepth).
    const at = wheelLane(best, p.squads, p.lord, threats);
    if (!deployNear(s, seat, best, strat === 'normal' ? normalDepth(best, at) : at)) break;
  }
  // Level-ups: cheapest relative upgrade first (lowest level, then higher cost tier).
  for (let guard = 0; guard < 40; guard++) {
    let best: Squad | null = null, bestScore = Infinity;
    for (const q of p.squads) {
      if (q.type === 'lord' || q.level >= 5) continue;
      const cost = levelUpCost(q.type, q.level);
      if (cost > p.gold - hold) continue;
      const score = q.level * 10 - UNITS[q.type].cost / 100 + (q.level === 1 || q.level === 3 ? -3 : 0);
      if (score < bestScore) { bestScore = score; best = q; }
    }
    if (!best) break;
    applyIntent(s, seat, { t: 'levelUp', squad: best.id });
  }
  // 4. Equip everything in the stash on the most valuable squad it works on (bestSquadFor).
  for (const it of [...p.stash]) {
    const q = bestSquadFor(it, p.squads, p.lord);
    if (q) applyIntent(s, seat, { t: 'equip', item: it.id, squad: q.id });
  }
  // 4b. Anti-air where the air is: when the enemy flew last round, archer-type squads (Archers, Bone Archers, Camel
  //     Archers) move under where its fliers were, as Hard's formation does. The rest of the army keeps its ground.
  antiAirPlacement(s, seat, threats);
  // 4c. A Muster's relocations: the squads that stand furthest from what they beat cross the field to it.
  if (relocationsLeft(p, s.round) > 0) applyLayout(s, seat, wheelSpots(s, seat, threats), KN.relocateMin);
  // 5. Lord placement.
  const lord = p.squads.find((q) => q.type === 'lord');
  if (lord && s.round === 1) {
    const spot = freeSpotNear(p.squads, seat, 'lord', seat === 0 ? placeFor('lord', p.squads, p.lord) : mirrorPos(placeFor('lord', p.squads, p.lord)), lord.id);
    if (spot) applyIntent(s, seat, { t: 'move', squad: lord.id, pos: spot });
  }
  // 6. The Lord's orders for the battle (he holds where he stands: this planner places him once).
  lordOrders(s, seat, KN, false);
  formations(s, seat, KN, threats);
  applyIntent(s, seat, { t: 'ready' });
}

// ---------------------------------------------------------------- hard

export function threatsOf(seat: Seat, enemy: Squad[] | null, enemyLord: LordId | null): Threat[] {
  if (!enemy) return [];
  return enemy.map((q) => {
    const [x, y] = own(seat, q.pos);
    if (q.type === 'lord') {
      const L = LORDS[enemyLord ?? 'marshal'];
      return { type: 'lord', value: valueOf(q), x, y, tags: L.tags, magic: L.damageType === 'magic', ranged: L.range > 400, backline: L.range > 400, body: bodyOf('lord', enemyLord ?? 'marshal')! };
    }
    const d = UNITS[q.type];
    return { type: q.type, value: valueOf(q), x, y, tags: d.tags, magic: d.damageType === 'magic', ranged: d.range > 400, backline: d.traits.includes('backline'), body: d };
  });
}

type Role = 'front' | 'flank' | 'ranged' | 'support' | 'artillery';
function roleOf(t: SquadType, lord: LordId | null): Role {
  // The Skylady flanks; the Drake Rider flies with the army (Plague Breath wants the enemy bunched in melee); a Lord who
  // shoots (the Roc Rider) stands with the bows.
  if (t === 'lord') return !lord ? 'support' : LORDS[lord].range > 400 ? 'ranged' : LORDS[lord].tags.includes('flier') && lord !== 'drakerider' ? 'flank' : 'support';
  const k = K(t);
  if (k === 'trebuchet') return 'artillery';
  if (k === 'clerics') return 'support';
  if (k === 'cavaliers' || k === 'pegasus' || k === 'wyvern' || k === 'dragon') return 'flank';
  return UNITS[t].range > 400 ? 'ranged' : 'front';
}

/** Value-weighted mean x of the threats `pred` selects, or `def` if none. */
function meanX(threats: Threat[], pred: (e: Threat) => number, def: number): number {
  let n = 0, d = 0;
  for (const e of threats) { const w = pred(e) * e.value; n += w * e.x; d += w; }
  return d > 0 ? n / d : def;
}

/**
 * Hard's formation for the whole army (seat 0 frame), placed against the enemy's last-round formation:
 * every squad lines up opposite the enemy squads it counters, raiders go to the flank holding the enemy backline
 * (and fewer enemy pikes), archers sit under enemy fliers, artillery behind the enemy's mass.
 */
export function hardLayout(p: PlayerState, threats: Threat[], staggerRef = STAGGER_REF): Map<number, Vec2> {
  const z = deployZone(0);
  const centre = meanX(threats, () => 1, 3999);
  // Flank choice: enemy backline value minus pike danger, per side of the field.
  let left = 0, right = 0;
  for (const e of threats) {
    // Raiders are Cavalry: the flank to avoid is the one where the class that beats Cavalry (Line) stands.
    const w = (e.backline ? e.value : 0) - (e.body.class === beatenBy('cavalry') ? 1.5 * e.value : 0) - (e.ranged && e.body.class === 'ranged' ? 0.3 * e.value : 0);
    if (e.x < 3999) left += w; else right += w;
  }
  // A tie goes to the same side in the bot's own frame for both seats, so the two plans are exact mirror images.
  const flankX = left > right ? 1100 : left < right ? 6900 : 1100;
  const rows: Record<Role, { q: Squad; want: number }[]> = { front: [], flank: [], ranged: [], support: [], artillery: [] };
  for (const q of p.squads) {
    const role = roleOf(q.type, p.lord);
    let want = centre;
    if (q.type !== 'lord') {
      const u = q.type as UnitType;
      if (role === 'flank') want = flankX;
      // Every squad lines up opposite what it beats on the wheel (archers under the enemy's fliers, pikes in front of
      // its cavalry, casters facing its swarm...).
      else if (role !== 'support') want = meanX(threats, (e) => wheelCv(UNITS[u], e.body) * (e.type === 'lord' ? 0.4 : 1), centre);
    } else if (role === 'flank') want = flankX;
    rows[role].push({ q, want });
  }
  // Support (Lord, clerics) stands behind the bulk of the frontline.
  const frontX = rows.front.length ? rows.front.reduce((a, r) => a + r.want, 0) / rows.front.length : centre;
  for (const r of rows.support) r.want = frontX;
  const out = new Map<number, Vec2>();
  const pack = (list: { q: Squad; want: number }[], y: number, spread: boolean): void => {
    if (!list.length) return;
    list.sort((a, b) => a.want - b.want || a.q.id - b.q.id);
    const gap = 60;
    const rad = list.map((r) => squadFootprint(r.q.type));
    const xs = list.map((r) => Math.round(r.want));
    // Spread a row around its wanted spots: sweep right, then pull back inside the zone.
    for (let i = 0; i < xs.length; i++) {
      const lo = i ? xs[i - 1] + rad[i - 1] + rad[i] + gap : z.x0 + rad[i];
      xs[i] = Math.max(xs[i], lo);
    }
    for (let i = xs.length - 1; i >= 0; i--) {
      const hi = i < xs.length - 1 ? xs[i + 1] - rad[i + 1] - rad[i] - gap : z.x1 - rad[i];
      xs[i] = Math.min(xs[i], hi);
    }
    for (let i = 0; i < xs.length; i++) {
      xs[i] = Math.max(z.x0, Math.min(z.x1, xs[i]));
      // Flank rows: stagger vertically so raiders of one flank do not queue in a line.
      const dy = spread ? (i % 2) * 450 : 0;
      out.set(list[i].q.id, [xs[i], y - dy]);
    }
  };
  pack(rows.front, 3650, false);
  pack(rows.flank, 3100, true);
  pack(rows.support, 2500, false);
  pack(rows.ranged, 1850, false);
  pack(rows.artillery, 800, false);
  if (KNOB.sync) speedStagger(p, out, 3650, staggerRef);
  return out;
}

/**
 * Timing by depth (Mechabellum's "timing of engagement"): melee squads are staggered by march speed so they reach
 * the river together. The slowest stands at `frontY`; a squad twice as fast starts twice as far from the river line.
 * Without it the tanks (Golems, Knights) reach the fight 5-9 s after the cheap infantry in front of them has
 * already taken the first blows (docs/reviews/POSITIONING-AND-ECONOMY.md section 1).
 */
function speedStagger(p: PlayerState, out: Map<number, Vec2>, frontY: number, ref: number): void {
  const z = deployZone(0);
  const melee = units(p.squads).filter((q) => UNITS[q.type as UnitType].range <= 400 && out.has(q.id));
  if (!melee.length || (ref <= 0 && melee.length < 2)) return;
  const LINE = 6000; // the middle of the river
  // Squads are locked where they are deployed, so the stagger is measured against a fixed pace (the slowest melee unit
  // of any roster, a Golem's): a squad bought in round 2 and one bought in round 8 still reach the river together.
  let vmin = ref > 0 ? ref : Infinity;
  for (const q of melee) vmin = Math.min(vmin, UNITS[q.type as UnitType].speed);
  for (const q of melee) {
    const v = UNITS[q.type as UnitType].speed;
    const y = LINE - Math.round(((LINE - frontY) * v) / vmin);
    const [x] = out.get(q.id)!;
    out.set(q.id, [x, Math.max(z.y0 + squadFootprint(q.type), Math.min(frontY, y))]);
  }
}

/** Hard staggers its melee by speed (switchable for the review scripts). */
const HARD_SPEED_SYNC = true;
/** The pace the stagger is measured against: the slowest melee unit of any roster (a Golem, 9). */
const STAGGER_REF = 9;

/**
 * Move squads to their layout spots (seat 0 frame), resolving the order so they never overlap on the way. Only what
 * the relocation rule lets move does: the Lord, this round's squads, and (with relocations left, i.e. after a Muster)
 * the locked squads that stand furthest from their spot, at least `relocateMin` cm off.
 */
export function applyLayout(s: MatchState, seat: Seat, layout: Map<number, Vec2>, relocateMin = 800): void {
  const p = s.players[seat];
  const locked = p.squads.filter((q) => layout.has(q.id) && squadLocked(q, s.round));
  const off = new Map(locked.map((q) => [q.id, offBy(seat, q, layout.get(q.id)!)] as [number, number]));
  // A squad already relocated this round moves on for free; the rest take the relocations left, worst-placed first.
  const moved = new Set(locked.filter((q) => { const h = squadHome(p, q.id); return !!h && (h[0] !== q.pos[0] || h[1] !== q.pos[1]); }).map((q) => q.id));
  const pick = locked.filter((q) => !moved.has(q.id) && off.get(q.id)! >= relocateMin).sort((a, b) => off.get(b.id)! - off.get(a.id)! || a.id - b.id).slice(0, relocationsLeft(p, s.round));
  const go = new Set([...moved, ...pick.map((q) => q.id)]);
  let todo = p.squads.filter((q) => layout.has(q.id) && (!squadLocked(q, s.round) || go.has(q.id)));
  for (let pass = 0; pass < 4 && todo.length; pass++) {
    const next: Squad[] = [];
    for (const q of todo) {
      const w = layout.get(q.id)!;
      const pos: Vec2 = seat === 0 ? w : mirrorPos(w);
      if (q.pos[0] === pos[0] && q.pos[1] === pos[1]) continue;
      if (!applyIntent(s, seat, { t: 'move', squad: q.id, pos }).ok) next.push(q);
    }
    if (next.length === todo.length) { todo = next; break; }
    todo = next;
  }
  for (const q of todo) {
    const w = layout.get(q.id)!;
    const spot = freeSpotNear(p.squads, seat, q.type, seat === 0 ? w : mirrorPos(w), q.id);
    if (spot) applyIntent(s, seat, { t: 'move', squad: q.id, pos: spot });
  }
}

/** Normal's anti-air placement: Hard's formation, applied to the archer-type squads only, when the enemy flew last round. */
function antiAirPlacement(s: MatchState, seat: Seat, all: Threat[]): void {
  // Flier squads only: a flying Lord who dives (the Skylady, the Drake Rider) is one rider, and archers parked under her
  // strip her army's flank. A flying Lord who shoots (the Roc Rider) hangs over her own backline all battle: the bows
  // go under her too.
  const threats = all.filter((e) => e.type !== 'lord' || e.ranged);
  if (!threats.some((e) => e.tags.includes('flier'))) return;
  const p = s.players[seat];
  const layout = hardLayout(p, threats);
  for (const q of p.squads) if (q.type === 'lord' || K(q.type) !== 'archers') layout.delete(q.id);
  applyLayout(s, seat, layout);
}

const MELEE_DPS: ReadonlySet<SquadType> = new Set(['berserkers', 'cavaliers', 'militia', 'wyvern', 'knights', 'pikemen', 'pegasus', 'golem']);
const MANY = (t: SquadType): number => (t === 'lord' ? 1 : UNITS[t].squadSize);

/**
 * How much `item` is worth on squad `q` (higher is better): its affixes and legendary power weighed by what the
 * squad does (no range on melee, toughness on the frontline, slaying against what the enemy fields...).
 */
function itemFit(item: Item, q: Squad, threats: Threat[], lord: LordId | null): number {
  const t = q.type;
  if (!canEquip(item, t, lord)) return -1;
  const role = roleOf(t, lord);
  const ranged = t === 'lord' ? LORDS[lord ?? 'marshal'].range > 400 : UNITS[t].range > 400;
  const k = KT(t);
  const healer = k === 'clerics';
  const tough = role === 'front' || k === 'lord' || k === 'golem' || k === 'dragon' || k === 'wyvern';
  let total = 0, magic = 0, ranged_ = 0;
  const tagShare: Partial<Record<Tag, number>> = {};
  for (const e of threats) {
    total += e.value;
    if (e.magic) magic += e.value;
    if (e.ranged) ranged_ += e.value;
    for (const g of e.tags) tagShare[g] = (tagShare[g] ?? 0) + e.value;
  }
  const share = (x: number): number => (total > 0 ? x / total : 0.25);
  let fit = 0;
  for (const a of [item.implicit, ...item.affixes]) {
    const base = a.value * AFFIXES[a.id].power;
    let m = 1;
    switch (a.id) {
      case 'vicious': case 'keen': case 'haste': m = healer ? 0.5 : 1.1; break;
      case 'leech': m = MELEE_DPS.has(k) ? 1.4 : ranged ? 0.6 : 0.8; break;
      case 'farreach': m = ranged ? 1.3 : 0; break;
      case 'stalwart': m = tough ? 1.3 : 0.6; break;
      case 'plated': m = tough ? 1.3 * (1 - share(magic)) + 0.1 : 0.4; break;
      case 'warding': m = 0.4 + 2.5 * share(magic); break;
      case 'thorns': m = role === 'front' ? 1.3 : 0.2; break;
      case 'fleet': m = role === 'flank' || role === 'front' ? 1.2 : 0.6; break;
      case 'slaying': m = 0.3 + 3 * share(a.tag ? tagShare[a.tag] ?? 0 : 0); break;
      case 'embers': m = MANY(t) >= 4 ? 1.2 : 0.7; break;
      // a slow is worth most against what runs at us (riders, fliers)
      case 'frost': m = 0.8 + 1.5 * share((tagShare.mounted ?? 0) + (tagShare.flier ?? 0)); break;
      case 'phoenix': m = MANY(t) <= 2 ? 2 : MANY(t) <= 4 ? 1.2 : 0.5; break;
      case 'command': m = 1; break;
      case 'marching': m = 1; break;
    }
    fit += base * m;
  }
  // A legendary power works only on the wheel classes it is built for (legendaryFits): elsewhere it is worth nothing.
  if (item.legendary && legendaryFits(item.legendary, t, lord)) {
    const L = item.legendary, n = MANY(t);
    const giants = threats.filter((e) => e.type === 'lord' || UNITS[e.type].class === 'giant').reduce((a, e) => a + e.value, 0);
    const packed = threats.filter((e) => e.type !== 'lord' && UNITS[e.type].squadSize >= 6).reduce((a, e) => a + e.value, 0);
    let m = 1;
    switch (L) {
      case 'stormcaller': case 'hydra_volley': m = 0.7 + 1.4 * share(packed); break;
      case 'kingsbane': m = 0.3 + 2.5 * share(giants); break;
      case 'undying_oath': case 'ember_crown': case 'gravebloom': m = n >= 6 ? 1.6 : n >= 3 ? 1.1 : 0.7; break;
      case 'mirror_aegis': m = 0.3 + 2.2 * share(ranged_); break;
      case 'warhorn': m = n >= 8 ? 1.6 : n >= 4 ? 1.1 : 0.9; break;
      case 'sunfire': m = role === 'front' ? 1.3 : 0.6; break;
      case 'lifebinder': m = tough ? 1.3 : 0.9; break;
      case 'bloodthirst': case 'earthshaker': case 'windrunner': case 'frostheart': m = 1.1; break;
    }
    fit += LEGENDARY_POWER * m * 1.5;
  }
  if (item.skill) {
    // Active skills: worth more where their trigger will hold often and their effect scales with the squad.
    const n = MANY(t);
    const fast = share((tagShare.mounted ?? 0) + (tagShare.flier ?? 0));
    const foot = share(tagShare.infantry ?? 0);
    let m = 1;
    switch (item.skill) {
      case 'fireball': case 'rain_of_arrows': case 'incendiary_payload': m = 0.7 + 0.9 * foot; break;
      case 'chain_lightning': m = 1.1; break;
      case 'frost_nova': m = 0.5 + 2 * fast; break;
      case 'mending_light': m = k === 'clerics' ? 1.3 : 1; break;
      case 'shield_wall': m = tough ? 1.3 : 0.8; break;
      case 'war_cry': m = role === 'front' || t === 'lord' ? 1.2 : 0.7; break;
      case 'cleave': m = n >= 4 ? 1.4 : 0.9; break;
      case 'fire_arrows': m = 1.2; break;
      case 'pinning_shot': m = 0.7 + 1.5 * fast; break;
      case 'thunderous_charge': case 'dive_strike': m = 1.3; break;
      case 'trample': m = 0.8 + 0.8 * foot; break;
    }
    fit += SKILLS[item.skill].power * m * 1.5;
  }
  // The wheel: a weapon is worth more to a squad when the enemy fields the class it beats, an armor when the enemy
  // fields the class that beats it, a relic (utility) a little either way (every item of an offer has the same budget,
  // so this is what the choice turns on).
  const cls = wheelClassOf(t, lord);
  if (cls) {
    let prey = 0, hunter = 0;
    for (const e of threats) {
      if (e.type === 'lord') continue;
      const ec = UNITS[e.type].class;
      if (ec === beatsClass(cls)) prey += e.value;
      if (beatsClass(ec) === cls) hunter += e.value;
    }
    fit *= 1 + (item.slot === 'weapon' ? 0.8 * share(prey) : item.slot === 'armor' ? 0.8 * share(hunter) : 0.4 * share(prey + hunter));
  }
  // Squads that matter more get the better gear.
  return fit * (valueOf(q) / 200);
}

/** Item-aware gearing: every item (stash and equipped) is re-assigned greedily to the squad it fits best. */
function hardEquip(s: MatchState, seat: Seat, threats: Threat[]): void {
  const p = s.players[seat];
  const items: Item[] = [...p.stash];
  for (const q of p.squads) for (const sl of ['weapon', 'armor', 'relic'] as Slot[]) if (q.items[sl]) items.push(q.items[sl]!);
  const cands: { it: Item; q: Squad; fit: number }[] = [];
  for (const it of items) for (const q of p.squads) if (slotOpen(q, it.slot) && canEquip(it, q.type, p.lord)) cands.push({ it, q, fit: itemFit(it, q, threats, p.lord) });
  cands.sort((a, b) => b.fit - a.fit || a.it.id - b.it.id || a.q.id - b.q.id);
  const used = new Set<number>(), taken = new Set<string>();
  const want = new Map<number, Squad>();
  for (const c of cands) {
    const key = `${c.q.id}:${c.it.slot}`;
    if (used.has(c.it.id) || taken.has(key)) continue;
    used.add(c.it.id); taken.add(key); want.set(c.it.id, c.q);
  }
  // Clear misplaced items first, then equip; whatever is left over waits in the stash.
  for (const q of p.squads) {
    for (const sl of ['weapon', 'armor', 'relic'] as Slot[]) {
      const it = q.items[sl];
      if (it && want.get(it.id) !== q) applyIntent(s, seat, { t: 'unequip', item: it.id });
    }
  }
  const slotOf = new Map(items.map((i) => [i.id, i.slot]));
  for (const [id, q] of want) if (q.items[slotOf.get(id)!]?.id !== id) applyIntent(s, seat, { t: 'equip', item: id, squad: q.id });
}

/**
 * How much Hard prefers levelling a squad over a new squad of equal counter value. Levels cost a flat share of the
 * unit (LEVEL_COST_PCT), so they are cheaper than a new squad but add less: the bias is tuned so that Hard spends
 * roughly a quarter of its gold on levels (docs/BALANCE.md).
 */
// (The value is KNOBS.base.levelBias.)
/**
 * Hard levels nothing before this round. (Waiting until round 4 tested about 6 points stronger head-to-head, but it
 * moved the faction and Lord balance by up to 18 points at Hard, so it is left for a full re-tune: see BALANCE.md.)
 */
const HARD_LEVEL_FROM = 1;
/**
 * The squad Hard would level next and how much it wants it, on unitScore's scale: what the squad's type is worth
 * against the enemy's last army, a little less for every level it already has (spread the levels), and more when its
 * next level opens a slot for an item waiting in the stash. Null when no level-up is affordable.
 */
function hardLevelPick(s: MatchState, seat: Seat, threats: Threat[], salt: number, hold: number): { q: Squad; w: number } | null {
  const p = s.players[seat];
  let best: Squad | null = null, bw = -1;
  for (const q of units(p.squads)) {
    if (q.level >= MAX_SQUAD_LEVEL) continue;
    const u = q.type as UnitType;
    if (levelUpCost(u, q.level) > p.gold - hold) continue;
    const others = p.squads.filter((o) => o !== q);
    let w = unitScore(s, seat, 'hard', u, others, threats, salt + 3) / (1 + 0.25 * (q.level - 1));
    for (const sl of ['armor', 'relic'] as Slot[]) if (q.level + 1 === SLOT_UNLOCK_LEVEL[sl] && p.stash.some((i) => i.slot === sl && canEquip(i, q.type, p.lord))) w *= 1.4;
    if (w > bw || (w === bw && best && q.id < best.id)) { bw = w; best = q; }
  }
  return best ? { q: best, w: bw } : null;
}

// ---------------------------------------------------------------- the Lord's stance

/**
 * The Lord's orders (LordStance), by what was measured (tools/review/orders.ts, docs/BALANCE.md): against a Hard that
 * leaves every Lord on 'advance',
 *  - a flying Lord who follows the dearest melee squad on the ground wins 64-70% (alone she reaches the enemy long
 *    before her army and meets every bow on the field);
 *  - the Ossuary Warden holding a post at the front edge wins 59% (Grave Taunt wants the enemy to come to him);
 *  - the Archmage following her dearest ranged squad wins 56-59%;
 *  - every other Lord does best on 'advance', and no Lord gains from 'hold' wherever he is posted (the Ossuary Warden
 *    at the front edge is the nearest to even, 49%), so the bots never hold.
 * Normal and the tournament strategies place the Lord once, behind the army, and re-form nothing: there only the
 * Roc Rider gains from following (55%); the Skylady and the Archmage lose by it (44%, 43%) and the Drake Rider is even, so
 * they stay on 'advance'.
 */
type LordOrder = 'front' | 'ranged' | 'hold';
const LORD_ORDER: Partial<Record<LordId, LordOrder>> = { skylady: 'front', drakerider: 'front', rocrider: 'front', archmage: 'ranged' };
const LORD_ORDER_CLASSIC: Partial<Record<LordId, LordOrder>> = { rocrider: 'front' };
/** Where a holding Lord is posted (seat 0 frame): the front edge of the deploy zone. */
const HOLD_POST_Y = 3800;

function lordOrders(s: MatchState, seat: Seat, KN: BotKnobs, hard: boolean): void {
  const repost = hard;
  const p = s.players[seat];
  const lordSq = p.squads.find((q) => q.type === 'lord');
  const order = p.lord && !KN.noStance ? (hard ? LORD_ORDER : LORD_ORDER_CLASSIC)[p.lord] : undefined;
  if (!lordSq) return;
  const us = units(p.squads);
  const dearest = (ok: (q: Squad) => boolean): Squad | null => {
    let best: Squad | null = null;
    for (const q of us) if (ok(q) && (!best || q.spent > best.spent)) best = q;
    return best;
  };
  const melee = (q: Squad): boolean => UNITS[q.type as UnitType].range <= 400 && !UNITS[q.type as UnitType].traits.includes('healer');
  let lead: Squad | null = null;
  if (order === 'front') lead = dearest((q) => melee(q) && !UNITS[q.type as UnitType].tags.includes('flier'));
  else if (order === 'ranged') lead = dearest((q) => !melee(q) && K(q.type as UnitType) !== 'trebuchet' && !UNITS[q.type as UnitType].traits.includes('healer'));
  if (lead) { applyIntent(s, seat, { t: 'stance', stance: 'follow', squad: lead.id }); return; }
  if (order === 'hold' && us.length) {
    if (repost) {
      const x = own(seat, lordSq.pos)[0];
      const spot = freeSpotNear(p.squads, seat, 'lord', own(seat, [x, HOLD_POST_Y]), lordSq.id);
      if (spot) applyIntent(s, seat, { t: 'move', squad: lordSq.id, pos: spot });
    }
    applyIntent(s, seat, { t: 'stance', stance: 'hold' });
    return;
  }
  if (lordSq.stance) applyIntent(s, seat, { t: 'stance', stance: 'advance' });
}

// ---------------------------------------------------------------- formations

/** A melee squad forms a wide line when at least this share of the enemy's last army (by gold) deals area damage. */
const WIDE_VS_SPLASH = 0.35;
/** A ranged squad stands in a wide line (it is rarely struck in melee) unless at least this share of the enemy raids (cavalry and fliers). */
const DEEP_VS_RAIDERS = 0.3;

/**
 * Formations (Formation in types.ts), read off the enemy's last army: a wide line takes less from splash and more from
 * melee blows. Against a Hard that leaves every squad deep this wins 54% (tools/review/orders.ts, docs/BALANCE.md);
 * every squad wide whatever the enemy fields wins 51%.
 */
function formations(s: MatchState, seat: Seat, KN: BotKnobs, threats: Threat[]): void {
  if (KN.noFormation) return;
  let all = 0, splash = 0, raid = 0;
  for (const e of threats) {
    if (e.type === 'lord') continue;
    all += e.value;
    if (UNITS[e.type].splash > 0) splash += e.value;
    if (e.body.class === 'cavalry' || e.tags.includes('flier')) raid += e.value;
  }
  for (const q of units(s.players[seat].squads)) {
    if (!hasFormation(q.type)) continue;
    const def = UNITS[q.type as UnitType];
    const melee = def.range <= 400 && !def.traits.includes('healer');
    const want: Formation = melee ? (all > 0 && splash >= all * WIDE_VS_SPLASH ? 'wide' : 'deep') : all > 0 && raid >= all * DEEP_VS_RAIDERS ? 'deep' : 'wide';
    if (formationOf(q) !== want) applyIntent(s, seat, { t: 'formation', squad: q.id, formation: want });
  }
}

export const KNOB = { noLevel: false, noLayout: false, bias: KNOBS.base.levelBias, sync: HARD_SPEED_SYNC, from: HARD_LEVEL_FROM };
function planHard(s: MatchState, seat: Seat, salt: number, strat: BotStrategy = 'hard'): void {
  const v = viewFor(s, seat);
  const p = s.players[seat];
  const threats = threatsOf(seat, v.enemy.lastArmy, v.enemy.lord);
  const KN = knobsOf(strat);
  // 0. Muster instead of the unlock, when the army stands far from where it is needed against the enemy's (locked)
  //    formation and no unit on offer is worth more than re-forming three squads.
  considerMuster(s, seat, KN, hardLayout(p, threats, KN.staggerRef), unlockEdge(p, (u) => unitScore(s, seat, 'hard', u, p.squads, threats, salt + 7) * (K(u) === 'dragon' || K(u) === 'golem' ? 1.25 : 1)));
  // 1. Drafts: the unlock that best answers what the enemy fields (and what we do not already answer).
  pickDrafts(s, seat, (opts) => {
    let best = opts[0], bw = -1;
    for (const u of opts) {
      // Late-game power units are worth a pick on their own.
      const w = unitScore(s, seat, 'hard', u, p.squads, threats, salt + 7) * (K(u) === 'dragon' || K(u) === 'golem' ? 1.25 : 1);
      if (w > bw) { bw = w; best = u; }
    }
    return best;
  });
  // 2. Loot: the item that would fit best somewhere in the army (counting slots a level-up opens).
  if (p.lootOffer) {
    let bi = 0, bf = -1;
    p.lootOffer.forEach((it, i) => {
      let f = 0;
      for (const q of p.squads) {
        const open = slotOpen(q, it.slot) || (q.type !== 'lord' && q.level + 1 >= SLOT_UNLOCK_LEVEL[it.slot]);
        if (!open || !canEquip(it, q.type, p.lord)) continue;
        const cur = q.items[it.slot];
        f = Math.max(f, itemFit(it, q, threats, p.lord) - (cur ? itemFit(cur, q, threats, p.lord) * 0.8 : 0));
      }
      if (f > bf) { bf = f; bi = i; }
    });
    applyIntent(s, seat, { t: 'pickLoot', index: bi });
  }
  // 3. Spend, choosing each time between the best new squad and the best level-up. A level-up is worth taking over a
  //    deployment when the squad it improves counters the enemy (HARD_LEVEL_BIAS times) better than the best
  //    affordable new squad would; a squad whose next level opens a slot for an item waiting in the stash jumps the
  //    queue. When nothing more can be deployed, the gold goes into levels.
  const hold = saveFor(s, p, p.gold, (u) => unitScore(s, seat, 'hard', u, p.squads, threats, salt));
  for (let guard = 0; guard < 60; guard++) {
    let best: UnitType | null = null, bw = -1;
    if (canDeploy(p)) {
      for (const u of p.unlocked) {
        if (UNITS[u].cost > p.gold - hold || !fits(p, u)) continue;
        const w = unitScore(s, seat, 'hard', u, p.squads, threats, salt);
        if (w > bw) { bw = w; best = u; }
      }
    }
    const lv = KNOB.noLevel || s.round < KNOB.from ? null : hardLevelPick(s, seat, threats, salt, hold);
    if (best && !(lv && lv.w * KNOB.bias > bw)) {
      if (deployNear(s, seat, best, placeFor(best, p.squads, p.lord))) continue;
    }
    if (!lv || !applyIntent(s, seat, { t: 'levelUp', squad: lv.q.id }).ok) break;
  }
  // 5. Gear, then 6. the formation against the enemy's last one: this round's squads and the Lord take their places in
  //    it, and after a Muster so do the three locked squads that stand furthest from theirs.
  hardEquip(s, seat, threats);
  if (!KNOB.noLayout) applyLayout(s, seat, hardLayout(p, threats, KN.staggerRef), KN.relocateMin);
  // 7. The Lord's orders for the battle, and the squads' formations.
  lordOrders(s, seat, KN, true);
  formations(s, seat, KN, threats);
  applyIntent(s, seat, { t: 'ready' });
}

/** Play one full planning turn for `seat` (lord pick, drafts, loot, equips, deploys, level-ups, ready). */
export function botPlan(s: MatchState, seat: Seat, strategy: BotStrategy, salt = 0): void {
  if (s.phase === 'lordPick') {
    if (!s.players[seat].lord) applyIntent(s, seat, { t: 'pickLord', lord: LORD_IDS[hash(s.seed, seat, salt, 'lord') % LORD_IDS.length] });
    return;
  }
  if (s.phase !== 'planning' || s.players[seat].ready) return;
  const level = levelOf(strategy);
  if (level === 'easy') return planEasy(s, seat, salt);
  if (level === 'hard') {
    return planHard(s, seat, salt, strategy);
  }
  return planClassic(s, seat, strategy, salt);
}

export type { Slot };
